#!/usr/bin/env node
/**
 * Client Reference build
 *
 * Reads packages/clients/generated/{domain}/sdk.gen.ts and types.gen.ts
 * (generated by @hey-api/openapi-ts from resolved OpenAPI specs) and produces
 * HTML reference pages showing endpoints, types, and search helpers.
 *
 * Domain list is authoritative from generated/index.ts.
 * Domain slug is parsed from ClientOptions.baseURL in types.gen.ts.
 * Source files shown in the subtitle are discovered dynamically from resolved/.
 *
 * Output:
 *   tools/client-reference/index.html        — landing page, one card per domain
 *   tools/client-reference/{domain}.html     — per-domain reference page
 *   tools/client-reference/search-helpers.html
 */

import { readdirSync, readFileSync, writeFileSync, mkdirSync, existsSync, rmSync } from 'fs';
import { resolve, dirname, join, basename } from 'path';
import { fileURLToPath } from 'url';
import { COLORS } from './lib/theme.js';
import { esc, titleCase, headerMetaSubtitle } from './lib/html.js';
import { twoColumnPage, singleColumnPage } from './lib/layout.js';
import { resolvedDir, resolvedSourcePairs } from './lib/paths.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const clientsArg = process.argv.find(a => a.startsWith('--clients='));
const contentArg = process.argv.find(a => a.startsWith('--content='));

if (!clientsArg || !contentArg) {
  console.error('Usage: node client-reference.js --clients=<path> --content=<path> [--resolved=<path>]');
  process.exit(1);
}

const clientsBase = resolve(process.cwd(), clientsArg.slice('--clients='.length));
const contentDir = resolve(process.cwd(), contentArg.slice('--content='.length));
const generatedClientsDir = clientsBase;
const outputDir = resolve(contentDir, 'client-reference');
mkdirSync(outputDir, { recursive: true });
readdirSync(outputDir).filter(f => f.endsWith('.html')).forEach(f => rmSync(join(outputDir, f)));

// Resolved source files clients are generated from — shown in each page's header metadata.
// Clients come from OpenAPI only; asyncapi is excluded even where it exists.
const SOURCE_SUFFIXES = ['openapi', 'state-machine'];
mkdirSync(outputDir, { recursive: true });

if (!existsSync(generatedClientsDir)) {
  console.error(`  generated clients dir not found at ${generatedClientsDir} — skipping client-reference build`);
  process.exit(0);
}

/** Compute the api-reference anchor ID for an endpoint. Must match api-reference/build.js. */
function endpointId(url, method) {
  return `op-${method}-${url.replace(/\//g, '-').replace(/[{}]/g, '').replace(/--+/g, '-').replace(/^-|-$/g, '')}`;
}

// ── Domain list ───────────────────────────────────────────────────────────────
// Parse generated/index.ts as the authoritative source of exported domains.

function parseDomainList(indexContent) {
  const domains = [];
  const re = /export \* as [\w-]+ from '\.\/([\w-]+)\/index\.js'/g;
  let m;
  while ((m = re.exec(indexContent)) !== null) domains.push(m[1]);
  return domains;
}

// ── TypeScript parsers ─────────────────────────────────────────────────────────

function extractBalanced(text, startIdx, openCh, closeCh) {
  let depth = 0, i = startIdx, start = -1;
  while (i < text.length) {
    if (text[i] === openCh) { if (depth === 0) start = i + 1; depth++; }
    else if (text[i] === closeCh) { depth--; if (depth === 0) return { content: text.slice(start, i), end: i + 1 }; }
    i++;
  }
  return { content: '', end: text.length };
}

/** Infer a human-readable label from a TypeScript type expression. */
function inferTsTypeLabel(expr) {
  const e = expr.trim().replace(/\s*\|\s*undefined$/, '').replace(/\s*\|\s*null$/, '').trim();
  if (!e || e === 'unknown' || e === 'any') return 'any';
  if (e === 'string') return 'string';
  if (e === 'number') return 'number';
  if (e === 'boolean') return 'boolean';
  if (e === 'null') return 'null';
  if (e === 'never') return 'never';
  if (e.endsWith('[]')) return `array[${inferTsTypeLabel(e.slice(0, -2))}]`;
  if (e.startsWith('Array<')) return `array[${inferTsTypeLabel(e.slice(6, -1))}]`;
  if (e.startsWith('{')) return 'object';
  if (e.startsWith('Record<')) return 'record';
  if (e.includes(' | ')) {
    const parts = e.split('|').map(v => v.trim());
    const isLiterals = parts.every(p => /^['"`]/.test(p) || p === 'undefined' || p === 'null');
    if (isLiterals) {
      const vals = parts.filter(p => p !== 'undefined' && p !== 'null').map(v => v.replace(/^['"`]|['"`]$/g, ''));
      return vals.length <= 5 ? `enum: ${vals.map(v => `"${v}"`).join(', ')}` : `enum (${vals.length} values)`;
    }
    return 'union';
  }
  if (/^['"`]/.test(e)) return `"${e.replace(/^['"`]|['"`]$/g, '')}"`;
  if (/^[A-Z]/.test(e)) return e; // PascalCase type reference
  return e;
}

/**
 * Parse top-level fields from a TypeScript object type body.
 * Returns [{ name, typeLabel, optional }]
 */
function parseSimpleTypeFields(body) {
  const stripped = body.replace(/\/\*\*[\s\S]*?\*\//g, '').replace(/\/\/[^\n]*/g, '');
  const segments = [];
  let depth = 0, start = 0;
  for (let i = 0; i < stripped.length; i++) {
    const ch = stripped[i];
    if (ch === '{' || ch === '[' || ch === '(') depth++;
    else if (ch === '}' || ch === ']' || ch === ')') depth--;
    else if (ch === ';' && depth === 0) { segments.push(stripped.slice(start, i).trim()); start = i + 1; }
  }
  if (start < stripped.length) segments.push(stripped.slice(start).trim());

  return segments.flatMap(seg => {
    if (!seg || seg.trimStart().startsWith('[')) return [];
    const m = seg.match(/^(\w+)(\?)?\s*:\s*([\s\S]+)$/);
    if (!m) return [];
    const name = m[1];
    if (name === 'url') return [];
    return [{ name, optional: m[2] === '?', typeLabel: inferTsTypeLabel(m[3].trim()) }];
  });
}

/**
 * Extract the body of a typed section (path/query/body) from a Data type body.
 * Returns null if the section is `never` or missing; otherwise the `{ ... }` body.
 */
function extractTypeSection(content, key) {
  const re = new RegExp(`\\b${key}\\s*\\??\\s*:\\s*`);
  const m = re.exec(content);
  if (!m) return null;
  const afterColon = content.slice(m.index + m[0].length).trimStart();
  if (afterColon.startsWith('never')) return null;
  const braceIdx = afterColon.indexOf('{');
  if (braceIdx === -1) return null;
  return extractBalanced(afterColon, braceIdx, '{', '}').content;
}

/**
 * Parse the slug from ClientOptions.baseURL in types.gen.ts.
 * Falls back to dirName if not found.
 */
function parseSlug(typesContent, dirName) {
  const m = typesContent.match(/baseURL:\s*['"`]https?:\/\/[^/'"]+\/([^/'"& ]+)/);
  return m?.[1] ?? dirName;
}

/**
 * Parse exported SDK functions from sdk.gen.ts.
 * Returns [{ name, method, url, title, description }]
 */
function parseEndpoints(sdkContent) {
  const endpoints = [];
  const re = /\/\*\*([\s\S]*?)\*\/\s*export const (\w+)\s*=/g;
  let m;
  while ((m = re.exec(sdkContent)) !== null) {
    const jsdoc = m[1];
    const name = m[2];
    const rest = sdkContent.slice(m.index + m[0].length, m.index + m[0].length + 800);
    const methodMatch = rest.match(/\)\.(get|post|patch|put|delete)\s*</i);
    const urlMatch = rest.match(/url:\s*['"`]([^'"`]+)['"`]/);
    if (!urlMatch) continue;
    const method = (methodMatch?.[1] ?? 'get').toUpperCase();
    const url = urlMatch[1];
    const lines = jsdoc.split('\n').map(l => l.replace(/^\s*\*\s?/, '').trim()).filter(l => l && !l.startsWith('@'));
    const title = lines[0] ?? name;
    const description = lines.slice(1).join(' ').trim();
    endpoints.push({ name, method, url, title, description });
  }
  return endpoints;
}

/**
 * Parse *Data types from types.gen.ts to extract parameters per endpoint.
 * Returns Map<funcName, { path: [], query: [], hasBody: bool }>
 */
function parseDataTypes(typesContent) {
  const map = new Map();
  const re = /export type ([A-Z][A-Za-z0-9]+)Data\s*=\s*\{/g;
  let m;
  while ((m = re.exec(typesContent)) !== null) {
    const typeName = m[1];
    const funcName = typeName[0].toLowerCase() + typeName.slice(1);
    const { content } = extractBalanced(typesContent, m.index + m[0].length - 1, '{', '}');
    const normalized = content.replace(/\s+/g, ' ');
    const hasBody = /\bbody\s*\??\s*:/.test(normalized) && !/\bbody\s*\??\s*:\s*never/.test(normalized);
    const pathBody = extractTypeSection(content, 'path');
    const queryBody = extractTypeSection(content, 'query');
    map.set(funcName, {
      path:    pathBody  ? parseSimpleTypeFields(pathBody)  : [],
      query:   queryBody ? parseSimpleTypeFields(queryBody) : [],
      hasBody,
    });
  }
  return map;
}

/**
 * Parse named domain types from types.gen.ts (excludes operation types).
 * Returns [{ name, fields }]
 */
function parseDomainTypes(typesContent) {
  const exclude = /(?:Data|Errors|Responses|Options)$/;
  const re = /export type ([A-Z][A-Za-z0-9]+)\s*=\s*\{/g;
  const results = [];
  let m;
  while ((m = re.exec(typesContent)) !== null) {
    const name = m[1];
    if (exclude.test(name)) continue;
    const { content } = extractBalanced(typesContent, m.index + m[0].length - 1, '{', '}');
    const fields = parseSimpleTypeFields(content);
    if (fields.length > 0) results.push({ name, fields });
  }
  return results;
}

/**
 * Parse named `as const` enum objects from types.gen.ts.
 * Returns [{ name, values }] where values are the string literal values.
 */
function parseDomainConsts(typesContent) {
  const results = [];
  const re = /^export const ([A-Z][A-Za-z0-9]+) = \{([\s\S]*?)\} as const;/gm;
  let m;
  while ((m = re.exec(typesContent)) !== null) {
    const name = m[1];
    const body = m[2];
    const values = [...body.matchAll(/:\s*'([^']+)'/g)].map(v => v[1]);
    if (values.length > 0) results.push({ name, values });
  }
  return results.sort((a, b) => a.name.localeCompare(b.name));
}

// ── Type cross-linking ─────────────────────────────────────────────────────────

const PRIMITIVES = new Set(['string', 'number', 'integer', 'boolean', 'null', 'void', 'undefined', 'any', 'unknown', 'object', 'array', 'record', 'union', 'never']);

function typeLink(label, knownTypes) {
  if (!label) return '';
  if (knownTypes?.has(label) && !PRIMITIVES.has(label.toLowerCase())) {
    return `<a href="#type-${esc(label)}" style="color:${COLORS.midBlue};text-decoration:none;font-weight:600;">${esc(label)}</a>`;
  }
  if (label.includes('"') || label.startsWith('enum')) {
    return `<span style="color:#b5490a;">${esc(label)}</span>`;
  }
  return `<span style="color:${COLORS.deepGreen};">${esc(label)}</span>`;
}

function renderFieldLines(fields, depth, knownTypes) {
  const indent = '  '.repeat(depth);
  return fields.map(f => {
    const opt = f.optional ? '?' : '';
    const typePart = typeLink(f.typeLabel, knownTypes);
    return `<div style="line-height:1.8;"><span style="opacity:0.5;">${esc(indent)}</span><span style="color:${COLORS.text};">${esc(f.name)}</span><span style="color:#888;">${opt}:</span> ${typePart}</div>`;
  }).join('');
}

// ── URL-based nav grouping ─────────────────────────────────────────────────────

/**
 * Convert a URL path segment to a safe anchor slug.
 */
function slugify(s) {
  return s.replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase();
}

/**
 * Return the nav group key for an endpoint URL.
 *
 * SDK URLs have no domain prefix — the domain is in ClientOptions.baseURL.
 * Groups by sub-resource: the first non-param segment after the first {param}.
 * Endpoints with no sub-resource (root CRUD) fall into the root resource group.
 *
 * /applications                        → "applications"
 * /applications/{id}                   → "applications"
 * /applications/{id}/submit            → "submit"
 * /applications/{id}/assets            → "assets"
 * /applications/{id}/assets/{assetId}  → "assets"
 */
function groupFromUrl(url) {
  const segments = url.split('/').filter(Boolean);
  const firstParamIdx = segments.findIndex(s => s.startsWith('{'));
  if (firstParamIdx === -1) return segments[0] ?? '';
  // First non-param segment after the first {param} is the sub-resource/action
  for (let i = firstParamIdx + 1; i < segments.length; i++) {
    if (!segments[i].startsWith('{')) return segments[i];
  }
  // No sub-resource — group under the root resource (segment before first param)
  return segments[firstParamIdx - 1] ?? segments[0] ?? '';
}

// ── HTML renderers ─────────────────────────────────────────────────────────────

function buildCallSignature(ep, domain) {
  const pathParams  = ep.parameters.filter(p => p.kind === 'Path');
  const queryParams = ep.parameters.filter(p => p.kind === 'Query');
  const hasBody     = ep.parameters.some(p => p.kind === 'Body');
  const qualifiedName = domain ? `${domain}.${ep.name}` : ep.name;
  if (!pathParams.length && !queryParams.length && !hasBody) return `${qualifiedName}()`;
  const opts = [];
  if (pathParams.length)  opts.push(`path: { ${pathParams.map(p => `${p.name}: ${p.typeLabel}`).join(', ')} }`);
  if (queryParams.length) opts.push(`query: { ${queryParams.map(p => `${p.name}${p.optional ? '?' : ''}: ${p.typeLabel.split(' ')[0]}`).join(', ')} }`);
  if (hasBody)            opts.push(`body: { ... }`);
  const oneLine = `${qualifiedName}({ ${opts.join(', ')} })`;
  return oneLine.length <= 72 ? oneLine : `${qualifiedName}({\n  ${opts.join(',\n  ')},\n})`;
}

function renderEndpointBlock(ep, apiSlug, knownTypes, id = '', domain = '') {
  const pathParams = ep.parameters.filter(p => p.kind === 'Path');
  const argSummary = pathParams.map(p => esc(p.name)).join(', ');
  const apiRefLink = apiSlug
    ? `<a href="../api-reference/${apiSlug}.html#${endpointId(ep.url, ep.method.toLowerCase())}" style="font-size:10px;background:${COLORS.paleBlue};border:1px solid ${COLORS.lightBlue};border-radius:3px;padding:1px 6px;color:${COLORS.midBlue};text-decoration:none;white-space:nowrap;flex-shrink:0;" title="View in API Reference">API ref →</a>`
    : '';
  const sig = buildCallSignature(ep, domain);
  const displayName = domain ? `${domain}.${ep.name}` : ep.name;
  const td = `padding:4px 10px;font-size:11.5px;border-bottom:1px solid #f2f2f2;`;
  const paramRows = ep.parameters.map(p => {
    const nameCell = (p.name === 'q' && p.kind === 'Query')
      ? `<a href="search-helpers.html" style="font-family:monospace;font-weight:600;color:${COLORS.midBlue};text-decoration:none;" title="See Search Helpers">${esc(p.name)} <span style="font-size:10px;font-weight:400;">search →</span></a>`
      : `<span style="font-family:monospace;font-weight:600;color:${COLORS.text};">${esc(p.name)}</span>`;
    return `<tr>
      <td style="${td}">${nameCell}</td>
      <td style="${td}font-family:monospace;">${typeLink(p.typeLabel, knownTypes)}</td>
      <td style="${td}color:#aaa;font-size:10px;">${esc(p.kind.toLowerCase())}</td>
      <td style="${td}font-size:10px;">${p.optional ? `<span style="color:#aaa;">optional</span>` : `<span style="color:${COLORS.richRed};font-weight:700;">required</span>`}</td>
    </tr>`;
  }).join('');
  const paramsHtml = paramRows ? `
    <div style="margin-top:10px;border:1px solid #eee;border-radius:4px;overflow:hidden;">
      <div style="font-size:9.5px;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;color:#aaa;padding:4px 10px;background:#fafafa;border-bottom:1px solid #eee;">Parameters</div>
      <table style="width:100%;border-collapse:collapse;"><tbody>${paramRows}</tbody></table>
    </div>` : '';
  return `<div ${id ? `id="${esc(id)}" ` : ''}class="content-item" style="border:1px solid ${COLORS.sandDark};border-radius:6px;margin-bottom:8px;overflow:hidden;">
  <details>
    <summary style="display:flex;align-items:center;gap:8px;padding:9px 12px;background:#fafafa;cursor:pointer;list-style:none;user-select:none;">
      <span style="font-size:10px;color:#aaa;width:12px;flex-shrink:0;" class="chevron">▶</span>
      <span style="font-family:monospace;font-size:13px;font-weight:700;color:${COLORS.darkBlue};">${esc(ep.name)}<span style="color:#aaa;font-weight:400;">(${argSummary})</span></span>
      ${ep.title ? `<span style="font-size:11px;color:#888;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(ep.title)}</span>` : '<span style="flex:1;"></span>'}
      ${apiRefLink}
      ${id ? `<a href="#${esc(id)}" class="permalink" title="Link to this method">#</a>` : ''}
    </summary>
    <div style="padding:10px 14px;border-top:1px solid #f0f0f0;">
      <pre style="font-family:'SFMono-Regular',Consolas,'Liberation Mono',Menlo,monospace;font-size:12px;background:#f6f8ff;border:1px solid #dde4f0;border-radius:4px;padding:8px 12px;overflow-x:auto;margin-bottom:${paramsHtml ? '10px' : '0'};">${esc(sig)}</pre>
      ${paramsHtml}
    </div>
  </details>
</div>`;
}

function renderTypeBlock(schema, knownTypes, id = '') {
  if (!schema.fields.length) return '';
  return `<div ${id ? `id="${esc(id)}" ` : ''}class="content-item" style="border:1px solid ${COLORS.sandDark};border-radius:6px;margin-bottom:8px;overflow:hidden;">
  <details>
    <summary style="display:flex;align-items:center;gap:8px;padding:9px 12px;background:#fafafa;cursor:pointer;list-style:none;user-select:none;">
      <span style="font-size:10px;color:#aaa;width:12px;flex-shrink:0;" class="chevron">▶</span>
      <code style="font-size:13px;font-weight:700;color:${COLORS.darkBlue};">${esc(schema.name)}</code>
      <span style="font-size:11px;color:#aaa;">${schema.fields.length} field${schema.fields.length !== 1 ? 's' : ''}</span>
      ${id ? `<a href="#${esc(id)}" class="permalink" title="Link to this type">#</a>` : ''}
    </summary>
    <div style="font-family:'SFMono-Regular',Consolas,'Liberation Mono',Menlo,monospace;font-size:12px;padding:10px 14px;background:#f6f8ff;border-top:1px solid #eee;">
      <div style="line-height:1.8;"><span style="color:#7c5cbf;">interface</span> <span style="color:${COLORS.darkBlue};font-weight:700;">${esc(schema.name)}</span> <span style="color:#666;">{</span></div>
      ${renderFieldLines(schema.fields, 1, knownTypes)}
      <div style="line-height:1.8;color:#666;">}</div>
    </div>
  </details>
</div>`;
}

function renderConstantBlock(c, domainDir) {
  const id = `const-${c.name}`;
  let subtitle, bodyHtml;

  if (c.kind === 'annotations') {
    subtitle = `map — annotations compiled from <code>${esc(domainDir)}-annotations*.yaml</code> at generation time`;
    const usageLine = [
      `${domainDir}.Annotations.schema['field/path']      // field annotations`,
      `${domainDir}.Annotations.operations['action-id']   // operation annotations`,
      `${domainDir}.Annotations.events['event.type']      // event annotations`,
    ].join('\n');
    bodyHtml = `
      <pre style="font-family:'SFMono-Regular',Consolas,'Liberation Mono',Menlo,monospace;font-size:12px;background:#f6f8ff;border:1px solid #dde4f0;border-radius:4px;padding:8px 12px;overflow-x:auto;margin-bottom:10px;">${esc(usageLine)}</pre>
      <div style="border:1px solid #eee;border-radius:4px;overflow:hidden;">
        <div style="font-size:9.5px;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;color:#aaa;padding:4px 10px;background:#fafafa;border-bottom:1px solid #eee;">Sub-maps</div>
        <table style="width:100%;border-collapse:collapse;"><tbody>
          <tr><td style="padding:4px 10px;font-size:11.5px;border-bottom:1px solid #f2f2f2;font-family:monospace;font-weight:600;">schema</td><td style="padding:4px 10px;font-size:11px;color:#555;border-bottom:1px solid #f2f2f2;">Field-level annotations keyed by JSON path</td></tr>
          <tr><td style="padding:4px 10px;font-size:11.5px;border-bottom:1px solid #f2f2f2;font-family:monospace;font-weight:600;">operations</td><td style="padding:4px 10px;font-size:11px;color:#555;border-bottom:1px solid #f2f2f2;">State machine action and OpenAPI operation annotations</td></tr>
          <tr><td style="padding:4px 10px;font-size:11.5px;font-family:monospace;font-weight:600;">events</td><td style="padding:4px 10px;font-size:11px;color:#555;">AsyncAPI event channel annotations</td></tr>
        </tbody></table>
      </div>`;
  } else {
    subtitle = `enum (${c.values.length} value${c.values.length !== 1 ? 's' : ''})`;
    const rows = c.values.map(v =>
      `<div style="line-height:1.8;"><span style="color:#b5490a;">'${esc(v)}'</span></div>`
    ).join('');
    bodyHtml = `<div style="font-family:'SFMono-Regular',Consolas,'Liberation Mono',Menlo,monospace;font-size:12px;padding:10px 14px;background:#f6f8ff;border-top:1px solid #eee;">${rows}</div>`;
  }

  return `<div id="${esc(id)}" class="content-item" style="border:1px solid ${COLORS.sandDark};border-radius:6px;margin-bottom:8px;overflow:hidden;">
  <details>
    <summary style="display:flex;align-items:center;gap:8px;padding:9px 12px;background:#fafafa;cursor:pointer;list-style:none;user-select:none;">
      <span style="font-size:10px;color:#aaa;width:12px;flex-shrink:0;" class="chevron">▶</span>
      <code style="font-size:13px;font-weight:700;color:${COLORS.darkBlue};">${esc(c.name)}</code>
      <span style="font-size:11px;color:#888;flex:1;">${subtitle}</span>
      <a href="#${esc(id)}" class="permalink" title="Link to this constant">#</a>
    </summary>
    <div style="border-top:1px solid #f0f0f0;">${bodyHtml}</div>
  </details>
</div>`;
}

// ── Load and process each domain ──────────────────────────────────────────────

const indexContent = readFileSync(join(generatedClientsDir, 'index.ts'), 'utf8');
const domainDirs = parseDomainList(indexContent);

const domains = domainDirs.map(dir => {
  const domainDir = join(generatedClientsDir, dir);
  const sdkContent   = readFileSync(join(domainDir, 'sdk.gen.ts'),   'utf8');
  const typesContent = readFileSync(join(domainDir, 'types.gen.ts'), 'utf8');

  const slug          = parseSlug(typesContent, dir);
  const endpointsList = parseEndpoints(sdkContent);
  const dataTypeMap   = parseDataTypes(typesContent);
  const types         = parseDomainTypes(typesContent);
  const knownTypes    = new Set(types.map(t => t.name));
  const apiSlug       = readdirSync(resolvedDir, { recursive: true }).some(f => typeof f === 'string' && basename(f) === `${slug}-openapi.yaml`) ? slug : null;
  const hasAnnotations = existsSync(join(domainDir, 'annotations.ts'));
  const enumConsts    = parseDomainConsts(typesContent).map(c => ({ ...c, kind: 'enum' }));
  const allConsts     = [
    ...enumConsts,
    ...(hasAnnotations ? [{ name: 'Annotations', kind: 'annotations' }] : []),
  ].sort((a, b) => a.name.localeCompare(b.name));

  const endpoints = endpointsList.map(ep => {
    const data = dataTypeMap.get(ep.name) ?? { path: [], query: [], hasBody: false };
    return {
      ...ep,
      parameters: [
        ...data.path.map(f  => ({ ...f, kind: 'Path'  })),
        ...data.query.map(f => ({ ...f, kind: 'Query' })),
        ...(data.hasBody ? [{ name: 'body', kind: 'Body', typeLabel: 'object', optional: false }] : []),
      ],
    };
  });

  return { dir, slug, label: titleCase(slug), endpoints, types, knownTypes, apiSlug, allConsts };
});

// ── Per-domain page ────────────────────────────────────────────────────────────

function buildDomainPage(d) {
  const apiRefNote = d.apiSlug
    ? `<a href="../api-reference/${d.apiSlug}.html" style="font-size:12px;color:${COLORS.midBlue};">View full API reference →</a>`
    : '';

  // Group endpoints by primary resource derived from URL.
  // Clients are generated from OpenAPI, so exclude asyncapi from source metadata.
  const sourcePairs = resolvedSourcePairs(d.slug, { include: SOURCE_SUFFIXES });

  const groups = new Map();
  for (const ep of d.endpoints) {
    const key = groupFromUrl(ep.url);
    if (!groups.has(key)) groups.set(key, { label: titleCase(key.replace(/-/g, ' ')), endpoints: [] });
    groups.get(key).endpoints.push(ep);
  }
  const useGroups = groups.size > 1;

  const typesSectionHtml = d.types.length
    ? `<section id="section-types" style="margin-bottom:2.5rem;">
        <h2 style="font-size:0.875rem;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;color:#888;margin-bottom:1rem;">Types (${d.types.length})</h2>
        ${d.types.map(t => renderTypeBlock(t, d.knownTypes, `type-${t.name}`)).join('')}
      </section>`
    : '';

  const constantsSectionHtml = d.allConsts.length
    ? `<section id="section-constants" style="margin-bottom:2.5rem;">
        <h2 style="font-size:0.875rem;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;color:#888;margin-bottom:1rem;">Constants (${d.allConsts.length})</h2>
        ${d.allConsts.map(c => renderConstantBlock(c, d.dir)).join('')}
      </section>`
    : '';

  const typesNavSection = d.types.length
    ? `<div class="nav-section">
        <div class="nav-section-label">Types</div>
        ${d.types.map(t => `<a href="#type-${esc(t.name)}" class="nav-link">${esc(t.name)}</a>`).join('')}
      </div>`
    : '';

  const constantsNavSection = d.allConsts.length
    ? `<div class="nav-section">
        <div class="nav-section-label">Constants</div>
        ${d.allConsts.map(c => `<a href="#const-${esc(c.name)}" class="nav-link">${esc(c.name)}</a>`).join('')}
      </div>`
    : '';

  let methodsNavItems, methodsMainHtml;
  if (useGroups) {
    methodsNavItems = [...groups.entries()].map(([key, g]) =>
      `<a href="#group-${slugify(key)}" class="nav-link">${esc(g.label)} <span class="nav-count">${g.endpoints.length}</span></a>`
    ).join('');
    methodsMainHtml = [...groups.entries()].map(([key, g]) =>
      `<section id="group-${slugify(key)}" style="margin-bottom:2.5rem;">
        <h2 style="font-size:0.875rem;font-weight:800;color:#888;margin-bottom:1rem;">${esc(g.label)} (${g.endpoints.length})</h2>
        ${g.endpoints.map(ep => renderEndpointBlock(ep, d.apiSlug, d.knownTypes, `ep-${ep.name}`, d.dir)).join('')}
      </section>`
    ).join('');
  } else {
    methodsNavItems = `<a href="#section-methods" class="nav-link">All methods <span class="nav-count">${d.endpoints.length}</span></a>`;
    methodsMainHtml = `<section id="section-methods" style="margin-bottom:2.5rem;">
      <h2 style="font-size:0.875rem;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;color:#888;margin-bottom:1rem;">Methods (${d.endpoints.length})</h2>
      ${d.endpoints.map(ep => renderEndpointBlock(ep, d.apiSlug, d.knownTypes, `ep-${ep.name}`, d.dir)).join('')}
    </section>`;
  }

  const navHtml = `<div class="nav-section">
      <div class="nav-section-label">Methods</div>
      ${methodsNavItems}
    </div>
    ${constantsNavSection}
    ${typesNavSection}`;
  const mainHtml = methodsMainHtml + constantsSectionHtml + typesSectionHtml;

  const html = twoColumnPage({
    title: `Safety Net Blueprint \u2014 Client Reference: ${esc(d.label)}`,
    breadcrumbs: [
      { label: 'Explorer',         href: '../../index.html' },
      { label: 'Client Reference', href: 'index.html'       },
      { label: d.label },
    ],
    headerHtml: `<div style="background:${COLORS.darkBlue};color:white;">
      <div style="padding:0.625rem 1.25rem;display:flex;align-items:center;gap:10px;">
        <span style="font-size:0.9375rem;font-weight:800;">${esc(d.label)}</span>
        <code style="font-size:11px;color:rgba(255,255,255,0.5);background:rgba(255,255,255,0.1);padding:1px 6px;border-radius:3px;">packages/generated/clients/${esc(d.dir)}</code>
      </div>
      ${headerMetaSubtitle(d.slug, sourcePairs, apiRefNote)}
    </div>`,
    navHtml,
    mainHtml,
    navWidth: 220,
    navSearch: true,
    extraStyle: `a { color: ${COLORS.midBlue}; }`,
  });

  writeFileSync(join(outputDir, `${d.dir}.html`), html, 'utf8');
  console.log(`  wrote client-reference/${d.dir}.html`);
}

// ── Helpers pages ──────────────────────────────────────────────────────────────
// Discovers utility .ts files at the root of generated/ (e.g. search-helpers.ts).
// Excludes index.ts and domain subdirectories.

const helperFiles = readdirSync(generatedClientsDir)
  .filter(f => f.endsWith('.ts') && f !== 'index.ts')
  .map(f => ({
    file: f,
    path: join(generatedClientsDir, f),
    label: titleCase(f.replace(/\.ts$/, '').replace(/-/g, ' ')),
    slug: f.replace(/\.ts$/, ''),
  }));

const SYNTAX_ROWS = [
  ['term',            'Full-text exact match',           'john'],
  ['*term*',          'Full-text contains',              '*john*'],
  ['term*',           'Starts with',                     'john*'],
  ['*term',           'Ends with',                       '*smith'],
  ['field:value',     'Exact field match',               'status:approved'],
  ['field:*value*',   'Contains (case-insensitive)',      'name:*john*'],
  ['field.nested:val','Nested field (dot notation)',      'address.state:CA'],
  ['field:>value',    'Greater than',                    'income:>1000'],
  ['field:>=value',   'Greater than or equal',           'income:>=1000'],
  ['field:<value',    'Less than',                       'income:<5000'],
  ['field:v1,v2',     'Match any (OR)',                   'status:approved,pending'],
  ['-field:value',    'Exclude / negate',                '-status:denied'],
  ['field:*',         'Field exists',                    'email:*'],
  ['-field:*',        'Field does not exist',            '-deletedAt:*'],
];

function renderSyntaxTable() {
  const thStyle = `padding:5px 10px;font-size:9.5px;font-weight:700;text-transform:uppercase;letter-spacing:0.04em;color:#888;text-align:left;background:#fafafa;border-bottom:1px solid #eee;`;
  const trs = SYNTAX_ROWS.map(([pat, desc, ex]) => `<tr>
    <td style="padding:5px 10px;font-family:monospace;font-size:11.5px;"><code style="font-size:11px;background:#f0f0f0;padding:1px 4px;border-radius:2px;">${esc(pat)}</code></td>
    <td style="padding:5px 10px;font-size:12px;color:#555;">${esc(desc)}</td>
    <td style="padding:5px 10px;font-family:monospace;font-size:11px;color:#888;">${esc(ex)}</td>
  </tr>`).join('');
  return `<table style="width:100%;border-collapse:collapse;border:1px solid #eee;border-radius:4px;overflow:hidden;">
    <thead><tr>
      <th style="${thStyle}">Pattern</th>
      <th style="${thStyle}">Description</th>
      <th style="${thStyle}">Example</th>
    </tr></thead>
    <tbody>${trs}</tbody>
  </table>`;
}

function parseQFunction(content) {
  const m = /\/\*\*([\s\S]*?)\*\/\s+export function q\(/.exec(content);
  if (!m) return null;
  const lines = m[1].split('\n').map(l => l.replace(/^\s*\*\s?/, '').trim());
  const description = lines.find(l => l && !l.startsWith('@')) ?? '';
  const examples = [];
  let inEx = false, exLines = [];
  for (const l of lines) {
    if (l.startsWith('@example')) { if (exLines.length) { examples.push(exLines.join('\n').trim()); exLines = []; } inEx = true; continue; }
    if (inEx) {
      if (l.startsWith('@')) { inEx = false; if (exLines.length) { examples.push(exLines.join('\n').trim()); exLines = []; } }
      else exLines.push(l);
    }
  }
  if (exLines.length) examples.push(exLines.join('\n').trim());
  return { description, examples };
}

function parseSearchMethods(content) {
  const methods = [];
  const re = /\/\*\*([\s\S]*?)\*\/\s+(\w+):\s*\((?:[^()]*|\([^()]*\))*\)[^=]*=>/g;
  let m;
  while ((m = re.exec(content)) !== null) {
    const rawDoc = m[1], name = m[2];
    const lines = rawDoc.split('\n').map(l => l.replace(/^\s*\*\s?/, '').trim());
    const description = lines.find(l => l && !l.startsWith('@')) ?? '';
    const exLines = [];
    let inEx = false;
    for (const l of lines) {
      if (l.startsWith('@example')) { inEx = true; continue; }
      if (inEx) { if (l.startsWith('@')) { inEx = false; break; } exLines.push(l); }
    }
    methods.push({ name, description, example: exLines.join('\n').trim() });
  }
  return methods;
}

function buildHelperPage(helper) {
  const content = readFileSync(helper.path, 'utf8');
  const methods = parseSearchMethods(content);
  const qFn = parseQFunction(content);

  const usageHtml = qFn?.examples.map(ex =>
    `<pre style="margin-top:0;font-size:11.5px;background:${COLORS.sandMid};border:1px solid ${COLORS.sandDark};border-radius:4px;padding:0.75rem 1rem;overflow-x:auto;white-space:pre;">${esc(ex)}</pre>`
  ).join('') ?? '';

  const methodsHtml = methods.map(m => `
    <div style="padding:0.875rem 0;border-bottom:1px solid ${COLORS.sandDark};">
      <code style="font-size:13px;font-weight:700;color:${COLORS.darkBlue};">search.${esc(m.name)}()<span style="color:${COLORS.deepGreen};font-weight:400;">: string</span></code>
      ${m.description ? `<p style="font-size:13px;color:#555;margin-top:4px;">${esc(m.description)}</p>` : ''}
      ${m.example ? `<pre style="margin-top:6px;font-size:11.5px;background:${COLORS.sandMid};border:1px solid ${COLORS.sandDark};border-radius:4px;padding:0.5rem 0.75rem;overflow-x:auto;">${esc(m.example)}</pre>` : ''}
    </div>`).join('');

  const html = singleColumnPage({
    title: `Safety Net Blueprint \u2014 Client Reference: ${esc(helper.label)}`,
    breadcrumbs: [
      { label: 'Explorer',         href: '../../index.html' },
      { label: 'Client Reference', href: 'index.html'       },
      { label: helper.label                                  },
    ],
    bodyHtml: `
  <div style="max-width:960px;margin:0 auto;padding:2.5rem 1.5rem 4rem;">
    <h1 style="font-size:1.5rem;font-weight:800;color:${COLORS.darkBlue};margin-bottom:0.375rem;">${esc(helper.label)}</h1>
    ${usageHtml ? `
    <div style="margin-bottom:2rem;">
      <h2 style="font-size:0.875rem;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;color:#888;margin-bottom:0.75rem;">Usage</h2>
      <div style="background:white;border:1px solid ${COLORS.sandDark};border-radius:8px;padding:1rem;">
        ${usageHtml}
      </div>
    </div>` : ''}
    <div style="display:grid;grid-template-columns:1fr ${qFn ? '1fr' : ''};gap:2rem;">
      <div>
        <h2 style="font-size:0.875rem;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;color:#888;margin-bottom:1rem;">Methods</h2>
        <div style="background:white;border:1px solid ${COLORS.sandDark};border-radius:8px;padding:0 1rem;">${methodsHtml}</div>
      </div>
      ${qFn ? `<div>
        <h2 style="font-size:0.875rem;font-weight:800;letter-spacing:0.06em;text-transform:uppercase;color:#888;margin-bottom:1rem;">Query Syntax Reference</h2>
        <div style="background:white;border:1px solid ${COLORS.sandDark};border-radius:8px;overflow:hidden;">${renderSyntaxTable()}</div>
      </div>` : ''}
    </div>
  </div>`,
  });

  writeFileSync(join(outputDir, `${helper.slug}.html`), html, 'utf8');
  console.log(`  wrote client-reference/${helper.slug}.html`);
}

// ── Index page ─────────────────────────────────────────────────────────────────

function buildIndexPage() {
  const rows = domains.map(d => `
    <a href="${esc(d.dir)}.html" style="display:grid;grid-template-columns:1fr auto;align-items:center;gap:1rem;padding:0.875rem 1rem;border-bottom:1px solid ${COLORS.sandDark};text-decoration:none;color:inherit;" onmouseover="this.style.background='${COLORS.sandMid}'" onmouseout="this.style.background=''">
      <div>
        <div style="font-size:14px;font-weight:700;color:${COLORS.darkBlue};margin-bottom:2px;">${esc(d.label)}</div>
        <code style="font-size:11px;color:#888;background:none;">packages/generated/clients/${esc(d.dir)}</code>
      </div>
      <div style="font-size:11px;color:#aaa;white-space:nowrap;">${d.endpoints.length} method${d.endpoints.length !== 1 ? 's' : ''} · ${d.allConsts.length} constant${d.allConsts.length !== 1 ? 's' : ''} · ${d.types.length} type${d.types.length !== 1 ? 's' : ''}</div>
    </a>`).join('');

  const helperRows = helperFiles.map(h => `
    <a href="${esc(h.slug)}.html" style="display:flex;align-items:center;justify-content:space-between;padding:0.875rem 1rem;background:white;border:1px solid ${COLORS.sandDark};border-radius:8px;text-decoration:none;color:inherit;margin-top:1rem;" onmouseover="this.style.background='${COLORS.sandMid}'" onmouseout="this.style.background=''">
      <div>
        <div style="font-size:14px;font-weight:700;color:${COLORS.darkBlue};margin-bottom:2px;">${esc(h.label)}</div>
        <code style="font-size:11px;color:#888;background:none;">packages/clients/utility/${esc(h.file)}</code>
      </div>
    </a>`).join('');

  const html = singleColumnPage({
    title: 'Safety Net Blueprint \u2014 Client Reference',
    breadcrumbs: [
      { label: 'Explorer',         href: '../../index.html' },
      { label: 'Client Reference'                           },
    ],
    bodyHtml: `
  <div style="max-width:800px;margin:0 auto;padding:2.5rem 1.5rem 4rem;">
    <h1 style="font-size:1.5rem;font-weight:800;color:${COLORS.darkBlue};margin-bottom:0.375rem;">Client Reference</h1>
    <p style="color:#666;margin-bottom:2rem;font-size:13px;">Generated TypeScript SDK clients — one per domain, generated from resolved OpenAPI specs.</p>
    <div style="background:white;border:1px solid ${COLORS.sandDark};border-radius:8px;overflow:hidden;">${rows}</div>
    ${helperRows}
  </div>`,
  });

  writeFileSync(join(outputDir, 'index.html'), html, 'utf8');
  console.log('  wrote client-reference/index.html');
}

// ── Build all ──────────────────────────────────────────────────────────────────

for (const d of domains) buildDomainPage(d);
for (const h of helperFiles) buildHelperPage(h);
buildIndexPage();
